def ring_area(points):
    return 0.5 * sum(
        points[index][0] * points[(index + 1) % len(points)][1]
        - points[(index + 1) % len(points)][0] * points[index][1]
        for index in range(len(points))
    )


def format_number(value):
    return f"{value:.6f}".rstrip("0").rstrip(".") or "0"


def render_svg():
    rings = []
    for is_hole, flat in MOTIF_RINGS:
        points = [(flat[index] / 1000, flat[index + 1] / 1000) for index in range(0, len(flat), 2)]
        area = ring_area(points)
        if (area > 0) == is_hole:
            points.reverse()
        svg_points = [(x, -y * V_STRETCH) for x, y in points]
        path = "M" + " L".join(f"{format_number(x)} {format_number(y)}" for x, y in svg_points) + " Z"
        rings.append(path)

    motif_path = " ".join(rings)
    copies = []
    for center_x, center_y in LATTICE:
        for column in (-1, 0, 1):
            for row in (-1, 0, 1):
                x = center_x + column * W
                y = H - center_y - row * H
                copies.append(f'<use href="#motif" transform="translate({format_number(x)} {format_number(y)})"/>')

    asset_path = Path(__file__).parent / "src" / "assets" / "damask-pattern.svg"
    asset_path.write_text(
        f'''<svg xmlns="http://www.w3.org/2000/svg" width="1550" height="1000" viewBox="0 0 {format_number(W)} {format_number(H)}">
  <defs>
    <path id="motif" d="{motif_path}"/>
    <pattern id="damask" patternUnits="userSpaceOnUse" width="{format_number(W)}" height="{format_number(H)}">
      <rect width="100%" height="100%" fill="{BG}"/>
      <g fill="{FG}" stroke="{FG}" stroke-width="0.00044" stroke-linejoin="round" fill-rule="nonzero">
        {''.join(copies)}
      </g>
    </pattern>
  </defs>
  <rect width="100%" height="100%" fill="url(#damask)"/>
</svg>
''',
        encoding="utf-8",
    )
    motif_asset_path = asset_path.with_name("damask-motif.svg")
    motif_asset_path.write_text(
        f'''<svg xmlns="http://www.w3.org/2000/svg" width="1000" height="1000" viewBox="-0.52 -0.52 1.04 1.04">
    <path d="{motif_path}" fill="{FG}" fill-opacity="0.35" stroke="{FG}" stroke-opacity="0.35" stroke-width="0.00044" stroke-linejoin="round" fill-rule="nonzero"/>
</svg>
''',
        encoding="utf-8",
    )
    return asset_path


if __name__ == "__main__":
    print(render_svg())
